using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class RenderProgressTests {
 static int count;static void Check(bool ok,string m){if(!ok)throw new Exception(m);count++;Console.WriteLine("PASS "+m);}static DateTime now;
 sealed class Voice:KokoroEngine {public bool Broken;public override void CheckFiles(){if(Broken)throw new IOException("test missing engine");}public override Wave Generate(string text,double speed,string path){return new Wave{Rate=24000,Samples=Enumerable.Range(0,(int)Math.Round(3/speed*24000)).Select(i=>(short)(5000*Math.Cos(i*.062))).ToArray()};}}
 public static int Main(){try{
  now=new DateTime(2026,11,1,8,0,0,DateTimeKind.Utc);var p=new RenderProgress(()=>now);p.Begin();Check(p.Read().Percent==0&&!p.Read().RemainingSeconds.HasValue,"Start/model loading has no fabricated deadline");now=now.AddSeconds(2);p.Update(10,"TTS");Check(!p.Read().RemainingSeconds.HasValue,"One short progress sample is insufficient for an ETA");now=now.AddSeconds(8);p.Update(25,"TTS");Check(p.Read().Percent==25&&Math.Abs(p.Read().RemainingSeconds.Value-30)<.001,"ETA uses measured elapsed processing time and observed work progress");Check(p.Read().Eta.StartsWith("~")&&p.Read().Eta.Contains("còn"),"An estimated finish is explicitly marked approximate");p.Update(10,"A later phase restarted its local percent");Check(p.Read().Percent==25,"Percent never moves backward across phases");now=now.AddSeconds(61);Check(!p.Read().RemainingSeconds.HasValue,"A long stalled step invalidates an obsolete deadline");p.Update(60,"Resumed");Check(p.Read().RemainingSeconds.HasValue,"A new measured advance refreshes the estimate");p.Update(100,"Publish still pending");Check(p.Read().Percent==99,"A progress callback cannot claim final 100% before verified completion");p.Finish(false);Check(p.Read().Percent==99&&!p.Read().RemainingSeconds.HasValue&&!p.Read().Running,"Failure or cancellation freezes progress and clears the live ETA");p.Begin();Check(p.Read().Percent==0,"A new execution recalculates progress instead of retaining a stale deadline");now=now.AddSeconds(20);p.Update(30,"TTS");p.Finish(true);Check(p.Read().Percent==100&&p.Read().FinishedUtc.HasValue&&p.Read().ElapsedSeconds==20,"Only successful completion records 100% and a real finish timestamp");
  now=new DateTime(2026,11,1,8,0,0,DateTimeKind.Utc);var active=new BatchJob(new RenderProgress(()=>now)){State=JobState.Running,Cues=new List<Cue>{new Cue{Text=String.Join(" ",Enumerable.Repeat("word",100))}}};active.Progress.Begin();active.Progress.Update(10,"a");now=now.AddSeconds(10);active.Progress.Update(25,"b");var future=new BatchJob{State=JobState.NeedsReview,Cues=new List<Cue>{new Cue{Text=String.Join(" ",Enumerable.Repeat("word",50))}}};var previous=new BatchJob{State=JobState.Failed};var done=new BatchJob{State=JobState.Done};var uncheckedJob=new BatchJob{Selected=false};Check(Math.Abs(RenderProgress.QueueRemaining(new[]{previous,active,future,done,uncheckedJob}).Value-50)<.001,"Queue ETA includes selected future retries, excludes previous failures/completed/unchecked jobs, and scales input work only as an estimate");
  string root=Path.Combine(Path.GetTempPath(),"BeoProgress "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string source=Path.Combine(root,"story.srt");File.WriteAllText(source,"1\n00:00:00,000 --> 00:00:03,200\nThis is the source narration.\n");var job=BatchJob.Load(source);job.Selected=false;job.Progress.Restore(47,32,false);string queue=Path.Combine(root,"queue.xml");QueueStore.Save(queue,new[]{job});var loaded=QueueStore.Load(queue).Single();Check(!loaded.Selected&&loaded.Progress.Read().Percent==47&&!loaded.Progress.Read().RemainingSeconds.HasValue,"Restart preserves file selection and measured progress, but never reuses a stale ETA");
  var a=new BeoAppearance{Theme="ocean",Scale=125,Page=1};string settings=Path.Combine(root,"appearance.xml");a.Save(settings);var b=BeoAppearance.Load(settings);Check(b.Theme=="ocean"&&b.Scale==125&&b.Page==1,"Theme/font/layout preferences round-trip independently of voice settings");File.WriteAllText(settings,"<appearance theme=\"unknown\" scale=\"999\" page=\"900\"/>");b=BeoAppearance.Load(settings);Check(b.Theme=="system"&&b.Scale==100&&b.Page==7,"Corrupt or unsupported appearance values fall back to supported values");
  foreach(var theme in new[]{"light","dark","warm","ocean","system"}){var palette=BeoPalette.Get(theme);Check(palette.Text!=palette.Surface&&palette.Accent!=palette.OnAccent,"Readable foreground/background pairs exist for "+theme);}
  var items=new List<BatchJob>{BatchJob.Load(source),BatchJob.Load(source)};items[1].Selected=false;int calls=0;BatchRunner.Run(items,false,()=>false,(j,path,progress)=>{calls++;progress(20,"TTS");progress(10,"New local phase");progress(100,"Not final");j.State=JobState.NeedsReview;return "";},(n,m)=>{});Check(calls==1&&items[1].State==JobState.Queued,"Core batch runner also protects unchecked files");Check(items[0].State==JobState.NeedsReview&&items[0].Progress.Read().Percent==99,"A job requiring review is never marked completed 100%");
  foreach(int mode in new[]{1,2}){
   var options=new RenderOptions{Locked=true,Prose=false,BaseSpeed=1,MinSpeed=.9,MaxSpeed=1.25,SlowShort=false,Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=source}};var seen=new List<int>();var original=BatchJob.Load(source).Cues;
   using(var engine=new Voice{Root=root,VoiceName="progress fixture",DeviceMode="cpu"}){
    var result=WorkflowRunner.Run(original,engine,options,Path.Combine(root,"mode"+mode+".wav"),mode,(words,o,path,owner,progress)=>{progress(0,"prepare");progress(50,"measure");progress(100,"measured");return words;},(n,m)=>{if(n==100)Check(options.WorkflowBundle!=null&&File.Exists(options.WorkflowBundle.Wave),"Mode "+mode+" exposes 100 only after the actual WAV bundle exists");seen.Add(n);});
    Check(result.Rendered&&result.Status=="FINAL_VERIFIED"&&seen.Last()==100,"Mode "+mode+" actual fixture render reaches verified completion");Check(seen.Zip(seen.Skip(1),(x,y)=>y>=x).All(x=>x),"Mode "+mode+" progress stays monotonic from preparation through final rendering");Check(result.Bundle.Reports.Length==mode&&File.ReadAllText(result.Bundle.Primary).Contains("BÉO VOICE STUDIO"),"Mode "+mode+" keeps its report count with the new application brand");
   }
  }
  Console.WriteLine("TOTAL RENDER PROGRESS "+count+" PASS. Deterministic clock, real persistence and fixture TTS with actual FFmpeg.");return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
